/* M.A.T — «Médico de Combate» (#/medico): juego de decisiones de un sanitario militar.
   El protocolo es el de las guías TCCC (Tactical Combat Casualty Care) del Comité TCCC / Joint Trauma System
   (versión de 1 de mayo de 2026) y el algoritmo MARCH-PAWS. Las fases son las de TCCC: bajo fuego, cuidados tácticos
   en el campo y evacuación táctica (TACEVAC). Las clases de shock son las del ATLS. Todo lo demás (ritmos de sangrado,
   la curva continua entre las clases del ATLS, la temperatura, cuánto tarda cada acción) está «simplificado para el juego».
   Regla de Jose (determinismo): una decisión correcta a tiempo SIEMPRE funciona; solo empeoran el herido los errores del
   jugador (orden equivocado, fármaco equivocado, demasiado tarde). No hay dados en los resultados: la semilla solo decide qué ocurre (en los casos fijos, nombre, edad, peso, grupo y lado;
   en las partidas infinitas, además, qué heridos, heridas, entorno, material, imprevistos y dilemas). Sin gore: marcadores y barras. */
const EN=()=>window.MAT_LANG==='en'; const L=(es,en)=>EN()?en:es;
const T=v=>Array.isArray(v)?(EN()?v[1]:v[0]):(v==null?'':v);
const esc=s=>String(s==null?'':s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function rng(seed){ let a=seed>>>0; return function(){ a=(a+0x6D2B79F5)|0; let t=Math.imul(a^(a>>>15),1|a); t=(t+Math.imul(t^(t>>>7),61|t))^t; return ((t^(t>>>14))>>>0)/4294967296; }; }
function interp(x,xs,ys){ if(x<=xs[0]) return ys[0]; for(let i=1;i<xs.length;i++){ if(x<=xs[i]){ const t=(x-xs[i-1])/(xs[i]-xs[i-1]); return ys[i-1]+(ys[i]-ys[i-1])*t; } } return ys[ys.length-1]; }
const fmt1=v=>(EN()?v.toFixed(1):v.toFixed(1).replace('.',','));
const fmt2=v=>(EN()?v.toFixed(2):v.toFixed(2).replace('.',','));
function mmss(s){ s=Math.max(0,Math.floor(s)); const h=Math.floor(s/3600), m=Math.floor(s/60)%60, x=s%60; return (h?h+':':'')+String(m).padStart(2,'0')+':'+String(x).padStart(2,'0'); }
function hhmm(s){ s=Math.floor(s); const h=Math.floor(s/3600)%24, m=Math.floor(s/60)%60; return String(h).padStart(2,'0')+':'+String(m).padStart(2,'0'); }
let APP=null, X=null, G=null, RAF=0, MODE='a';

