function gChest(){ return [
  {ph:'tfc',m:'R',q:['Respiración: la herida del pecho sopla con cada respiración.','Breathing: the chest wound sucks air with each breath.'],hint:['Herida torácica abierta: sello torácico con válvula enseguida, y vigilar porque puede aparecer un neumotórax a tensión.','Open chest wound: vented chest seal right away, and watch for a tension pneumothorax.'],
   opts:[O('Sello torácico con válvula sobre la herida','Vented chest seal over the wound',OK,{t:45,end:S=>{ctl('c1')(S);S.seal=1;S.tensGrow=1/260;mark(S,'seal',L('Sello','Seal'),wd(S,'c1').x,wd(S,'c1').y);logc(S,'Sello torácico con válvula','Vented chest seal');}},['TCCC: toda herida torácica abierta lleva un sello torácico con válvula; vigilar después si aparece neumotórax a tensión.','TCCC: every open chest wound gets a vented chest seal; then monitor for tension pneumothorax.']),
    O('Taparla con gasas y esperar','Cover it with gauze and wait',NO,{t:40,end:S=>{S.tensGrow=1/300;}},['Las gasas no sellan: entra aire en el tórax. TCCC pide sello torácico.','Gauze doesn’t seal: air keeps entering the chest. TCCC calls for a chest seal.'])]},
  {ph:'tfc',m:'R',when:S=>true,enter:S=>{ if(S.tension<0.55) S.tension=0.55; S.tensGrow=1/220; },q:S=>['Empeora: le cuesta mucho respirar, la saturación baja ('+Math.round(vitals(S).spo)+' %) y la tensión cae.','He is worse: struggling to breathe, oxygen saturation dropping ('+Math.round(vitals(S).spo)+' %) and blood pressure falling.'],hint:['Herida de tórax + dificultad respiratoria creciente + saturación <90 % + shock = neumotórax a tensión. Primero levantar el sello; si no mejora, descompresión con aguja.','Chest wound + worsening distress + saturation <90 % + shock = tension pneumothorax. First burp the seal; if no better, needle decompression.'],
   opts:[O('Levantar el sello y, si no mejora, aguja 14 G de 8,25 cm en el 5.º espacio intercostal, línea axilar anterior, hasta el cono; mantener 5-10 s y dejar el catéter','Burp the seal and, if no better, a 14 G 3.25" needle at the 5th intercostal space, anterior axillary line, to the hub; hold 5-10 s and leave the catheter',OK,{t:60,end:S=>{S.tension=0;S.tensGrow=0;S.ndc=1;const w=wd(S,'c1');mark(S,'ndc','NDC',S.side==='L'?100:40,104);logc(S,'Descompresión con aguja (5.º EIC, LAA)','Needle decompression (5th ICS, AAL)');}},['TCCC: con sello, primero levantarlo; descomprimir del lado de la lesión con aguja de 14 G o 10 G de 3,25" en el 5.º EIC línea axilar anterior o 2.º EIC línea medioclavicular. Éxito: mejora la respiración o la saturación vuelve a ≥90 % (puede tardar minutos).','TCCC: with a seal in place, burp it first; decompress the injured side with a 14 G or 10 G 3.25" needle at the 5th ICS anterior axillary line or 2nd ICS mid-clavicular line. Success: breathing improves or saturation returns to ≥90 % (may take minutes).']),
    O('Descompresión con un catéter de vía IV normal (18 G, 3 cm) en el 2.º espacio intercostal','Decompress with a standard IV catheter (18 G, 3 cm) at the 2nd intercostal space',NO,{t:60,end:S=>{S.tension=Math.max(0,S.tension-0.1);}},['Demasiado corto y fino: no llega a la pleura en muchos soldados. TCCC exige aguja de 14 G o 10 G de 3,25 pulgadas (8,25 cm). Sigue la tensión.','Too short and thin: it doesn’t reach the pleura in many soldiers. TCCC requires a 14 G or 10 G 3.25-inch (8.25 cm) needle. The tension persists.'],'t26',2),
    O('Pinchar en el centro del pecho, junto al esternón','Puncture the middle of the chest, next to the sternum',NO,{t:60,h:{hr:12,sbp:-12}},['TCCC: nunca insertar la aguja por dentro de la línea del pezón; ahí están el corazón y los grandes vasos. Sigue la tensión.','TCCC: never insert the needle medial to the nipple line; the heart and great vessels are there. The tension persists.'],'t26',2),
    O('Darle sangre: la tensión baja es por la hemorragia','Give blood: the low pressure is from bleeding',NO,{t:120},['Ha perdido poca sangre. TCCC: en shock que no responde, pensar en neumotórax a tensión sin tratar.','He has lost little blood. TCCC: in shock that doesn’t respond, think of an untreated tension pneumothorax.']),
    O('Esperar a ver cómo evoluciona','Wait and see',NO,{t:60},['TCCC: sin tratamiento el neumotórax a tensión pasa del distrés al shock y a la parada.','TCCC: untreated, tension pneumothorax progresses from distress to shock and cardiac arrest.'],'t26',2)]},
 ]; }
function gTalk(){ return {ph:'tfc',m:'A',q:['Vía aérea: te habla, aunque le cuesta.','Airway: he talks to you, with effort.'],hint:['Si habla, la vía aérea está libre. Al consciente se le deja en la postura que mejor le proteja la vía aérea, también sentado.','If he talks, the airway is open. Let a conscious casualty take whatever position best protects the airway, sitting up included.'],
  opts:[O('Vía aérea libre: dejarle en la postura que él prefiera','Airway open: let him take the position he prefers',OK,{t:10},['TCCC: permitir al consciente la postura que mejor proteja su vía aérea.','TCCC: allow a conscious casualty any position that best protects the airway.']),
   O('Tumbarle boca arriba a la fuerza','Force him flat on his back',NO,{t:20},['Al consciente no se le fuerza la postura: respira peor.','Don’t force a conscious casualty’s position: he breathes worse.'])]}; }
function gEye(){ return {ph:'tfc',m:'W',q:['Ojo: un fragmento le ha herido el ojo '+'y ve borroso.','Eye: a fragment has injured his eye and his vision is blurred.'],hint:['TCCC: herida penetrante de ojo: prueba rápida de visión, protector ocular RÍGIDO (nunca un parche que apriete) y antibiótico cuanto antes.','TCCC: penetrating eye injury: quick vision test, a RIGID eye shield (never a pressure patch) and an antibiotic as soon as possible.'],
  opts:[O('Prueba rápida de visión, anotarla y cubrir el ojo con un protector rígido, sin apretar','Quick vision test, record it and cover the eye with a rigid shield, no pressure',OK,{t:45,end:S=>{const w=wd(S,'e1'); if(w){w.ctl=1; mark(S,'eye',L('Protector','Shield'),w.x,w.y);} logc(S,'Protector ocular rígido','Rigid eye shield');}},['TCCC: en herida penetrante de ojo, prueba rápida de agudeza visual, protector ocular rígido (NO un parche compresivo) y ceftriaxona o cefadroxilo cuanto antes.','TCCC: for penetrating eye trauma, a quick visual acuity test, a rigid eye shield (NOT a pressure patch) and ceftriaxone or cefadroxil as soon as possible.']),
   O('Parche compresivo bien apretado sobre el ojo','A tight pressure patch over the eye',NO,{t:40},['Error grave: TCCC dice protector rígido y NUNCA un parche compresivo: apretar un ojo herido puede vaciarlo.','Serious error: TCCC says a rigid shield and NEVER a pressure patch: pressing on an injured eye can make it worse.'],'t26',2),
   O('Lavarlo y sacar el fragmento con unas pinzas','Rinse it and pull the fragment out with tweezers',NO,{t:60},['Nunca se saca un cuerpo extraño de un ojo herido en el campo: se protege con un protector rígido y se evacúa.','Never remove a foreign body from an injured eye in the field: shield it and evacuate.'],'t26',2)]}; }
function gSplint(){ return {ph:'tfc',m:'S',q:['Férulas: el antebrazo está deformado, posible fractura cerrada.','Splints: the forearm is deformed, a possible closed fracture.'],hint:['TCCC: entablillar las fracturas y volver a comprobar los pulsos.','TCCC: splint fractures and recheck pulses.'],
  opts:[O('Entablillar el brazo tal como está y volver a comprobar el pulso de la muñeca','Splint the arm as it lies and recheck the wrist pulse',OK,{t:90,end:S=>logc(S,'Férula de brazo','Arm splint')},['TCCC: entablillar las fracturas y volver a comprobar los pulsos.','TCCC: splint fractures and recheck pulses.']),
   O('Recolocar el hueso tirando fuerte','Realign the bone by pulling hard',NO,{t:60},['TCCC pide entablillar, no recolocar a la fuerza.','TCCC says splint it, not force it back.'])]}; }
function gHidden(){ return {ph:'tfc',m:'M',ev:1,q:['¡Imprevisto! Al cortarle la ropa ves sangre bajo el pantalón: otra herida en la parte de atrás del muslo que no habías visto. Sangra de forma continua, sin borbotones.','Surprise! Cutting away his clothes you see blood under the trousers: another wound on the back of the thigh you had missed. It bleeds steadily, not spurting.'],hint:['Para una herida que se puede comprimir: gasa hemostática empaquetada con al menos 3 minutos de presión directa y vendaje compresivo.','For a compressible wound: haemostatic gauze packed with at least 3 minutes of direct pressure and a pressure bandage.'],
  opts:[O('Empaquetar gasa hemostática, 3 minutos de presión directa y vendaje compresivo','Pack haemostatic gauze, 3 minutes of direct pressure and a pressure bandage',OK,{t:220,end:S=>{ctl('h1')(S);logc(S,'Herida oculta: gasa hemostática + presión','Hidden wound: haemostatic gauze + pressure');}},['TCCC: aplicar las gasas hemostáticas con al menos 3 minutos de presión directa. Por eso TCCC insiste en buscar heridas no detectadas.','TCCC: apply haemostatic dressings with at least 3 minutes of direct pressure. That is why TCCC insists on looking for unrecognised wounds.']),
   O('Otro torniquete en ese muslo','Another tourniquet on that thigh',NO,{t:40,end:S=>{ctl('h1')(S);addTQ(S,'h1','TQ');}},['No sangra a borbotones: un torniquete innecesario daña el miembro. Bastaba gasa y presión.','It isn’t spurting: an unneeded tourniquet harms the limb. Gauze and pressure were enough.']),
   O('Dejarla para el hospital: sangra poco','Leave it for the hospital: it bleeds little',NO,{t:20},['Sigue sangrando sin parar y suma litros. TCCC: controlar todas las fuentes de sangrado.','It keeps bleeding and adds up. TCCC: control all sources of bleeding.'])]}; }
function gPlasma(){ return {ph:'tfc',m:'C',bl:1,repeat:S=>shocked(S),q:S=>[shocked(S)?'No hay sangre total, solo plasma liofilizado. Sigue en shock: pulso radial '+radial(S)+'. ¿Qué haces?':'Reevalúa tras la unidad de plasma: pulso radial '+radial(S)+'. ¿Sigues?',shocked(S)?'No whole blood, only freeze-dried plasma. Still in shock: radial pulse '+radial(S)+'. What do you do?':'Reassess after the plasma unit: radial pulse '+radial(S)+'. Do you continue?'],
  hint:['TCCC: si no hay sangre total, el orden sigue con componentes y al final plasma o hematíes solos. Reevaluar tras cada unidad y parar al alcanzar el objetivo.','TCCC: if there is no whole blood, the order continues with components and finally plasma or red cells alone. Reassess after each unit and stop at the end point.'],
  opts:[O('Una unidad de plasma liofilizado y reevaluar','One unit of freeze-dried plasma, then reassess',S=>shocked(S),{t:240,end:S=>{S.trans+=0.35;logc(S,'Plasma liofilizado, 1 unidad','Freeze-dried plasma, 1 unit');}},['TCCC: sin sangre total, plasma (o hematíes) y reevaluar tras cada unidad. Cuánto sube cada unidad: simplificado para el juego.','TCCC: without whole blood, plasma (or red cells), reassessing after each unit. How much each unit helps: simplified for the game.']),
   O('Dos litros de suero salino a chorro','Two litres of saline wide open',NO,{t:240,end:S=>{S.crys+=2;S.temp-=0.4;S.coag+=0.25;S.off.sbp-=4;}},['El suero diluye la sangre y la enfría; TCCC no lo usa para reanimar el shock hemorrágico si hay hemoderivados.','Saline dilutes and cools the blood; TCCC doesn’t use it to resuscitate haemorrhagic shock when blood products exist.'],'t26',2),
   O('Parar: tiene pulso radial palpable, objetivo alcanzado','Stop: palpable radial pulse, end point reached',S=>!shocked(S),{t:10},['TCCC: dejar de dar líquidos al alcanzar pulso radial palpable, mejor estado mental o PAS de 100.','TCCC: stop fluids at a palpable radial pulse, improved mental status or SBP 100.'])]}; }

/* plantillas por mecanismo; 'mx' = clave del mecanismo para el título del incidente */
const GTPL={muslo:{mx:'gsw',cat:'T1',lim:1},brazo:{mx:'gsw',cat:'T1',lim:1},amputacion:{mx:'ied',cat:'T1',lim:1},torax:{mx:'gsw',cat:'T1',chest:1},ingle:{mx:'frag',cat:'T1'},
 cabeza:{mx:'ied',cat:'T1'},quemado:{mx:'fire',cat:'T1'},frio:{mx:'cold',cat:'T2'},pelvis:{mx:'roll',cat:'T1'},leve:{mx:'frag',cat:'T3'}};
const GMX={gsw:['Emboscada','Ambush'],ied:['Artefacto explosivo','Explosive device'],frag:['Ataque de mortero','Mortar attack'],fire:['Vehículo en llamas','Burning vehicle'],cold:['Paso del río','River crossing'],roll:['Vuelco del vehículo','Vehicle rollover']};
const GCAT={T1:['Inmediato (T1)','Immediate (T1)'],T2:['Diferido (T2)','Delayed (T2)'],T3:['Leve (T3)','Minimal (T3)'],T4:['Expectante (T4)','Expectant (T4)']};
const GCATW={T1:['necesita actuación en minutos para no morir: hemorragia sin controlar, vía aérea o respiración comprometidas, o shock','needs action within minutes to survive: uncontrolled bleeding, compromised airway or breathing, or shock'],
 T2:['necesita tratamiento, pero su estado permite esperar un poco sin poner en peligro inmediato la vida, el miembro o la vista','needs treatment, but his condition allows a short wait without immediate danger to life, limb or sight'],
 T3:['lesiones menores: puede cuidarse solo e incluso ayudar','minor injuries: he can look after himself and even help'],
 T4:['sin signos de vida tras una explosión o un disparo','no signs of life after a blast or gunshot']};
function gTpl(id){ return id==='brazo'?GBRAZO():id==='leve'?GLEVE:id==='pelvis'?GPELV:caseById(id); }
function gOrd(st,r){ st.order=shuf(st.opts.map((o,i)=>i),r); return st; }
function gPrio(g){ let best=-1,bs=-1; g.pts.forEach((S,k)=>{ if(S.dead||S.done) return; const st=S.steps[S.step]; let s=0;
  S.wounds.forEach(w=>{ if(!w.hidden&&(w.ctl||0)<1) s+=w.rate*(1-(w.ctl||0))*1000; });
  s+=S.tension*300; if(S.flags.anaph&&!S.flags.epi) s+=500; if(st&&['M','A','R','CUF'].includes(st.m)) s+=50; if(st&&st.ph==='cuf') s+=60;
  if(defic(S)>=0.3&&S.trans<0.5) s+=250; if(S.burn&&!S.burnFluid) s+=40;
  if(s>bs){bs=s;best=k;} }); return best<0?g.cur:best; }
/* un herido generado: plantilla + expediente + entorno + módulos */
function gCase(r,id,o,ctx){
 const b=gTpl(id); const tp=GTPL[id];
 const cs=Object.assign({},b,{gen:1,tpl:id,cat:(id==='leve'&&(o.sec||[]).includes('eye'))?'T2':tp.cat});
 let kind=b.abx; if(['std','amox','ceph','moxi'].includes(b.abx)){ const kk=['std','std','amox','ceph','moxi']; kind=kk[Math.floor(r()*kk.length)]; }
 else if(b.abx==='tbi'&&r()<0.4) kind=r()<0.5?'amox':'ceph';
 cs.abx=kind; cs.allergy=kind==='tbi'?b.allergy:(GALG[kind]||b.allergy);
 cs.late=o.late&&kind!=='std'&&kind!=='tbi'&&kind!=='burn'&&kind!=='none'?1:0;
 if(cs.late){ cs.allergyReal=cs.allergy; cs.allergy=['no consta (no lo sabe nadie aún)','not recorded (nobody knows yet)']; }
 cs.meds=GMEDS[Math.floor(r()*GMEDS.length)];
 const env=ctx.env, wx=ctx.wx;
 if(!o.single) cs.lost0=b.lost0*0.8;
 cs.tDrop=b.tDrop*wx.k*(env.cold?1.2:1)*(env.hot?0.7:1); cs.wet=b.wet||wx.wet?1:0;
 const side=r()<0.5?'L':'R';
 cs.wounds=b.wounds.map(w=>Object.assign({},w));
 const sec=o.sec||[];
 if(sec.includes('chest')) cs.wounds.push({id:'c1',at:'chest',rate:0.012,lab:['Herida torácica abierta','Open chest wound']});
 if(sec.includes('eye')) cs.wounds.push({id:'e1',at:'eye',rate:0,lab:['Herida penetrante en el ojo','Penetrating eye wound']});
 if(o.hidden) cs.wounds.push({id:'h1',at:'thigh',rate:0.008,hidden:1,fixed:side==='L'?'R':'L',lab:['Herida en la parte de atrás del muslo','Wound on the back of the thigh']});
 const bi=b.init; cs.init=S=>{ S.side=side; S.name=ctx.name(); S.meds=cs.meds; if(bi) bi(S); };
 const extra=[]; if(sec.includes('chest')) extra.push(['+ herida en el pecho','+ chest wound']); if(sec.includes('eye')) extra.push(['+ ojo','+ eye']); if(sec.includes('fx')) extra.push(['+ fractura de brazo','+ broken arm']);
 cs.title=[b.title[0]+(extra.length?' '+extra.map(x=>x[0]).join(' '):''),b.title[1]+(extra.length?' '+extra.map(x=>x[1]).join(' '):'')];
 const bm=b.mech; cs.mech=S=>{ const m=bm(S); const add=[];
  if(sec.includes('chest')) add.push(['Además, un impacto en el pecho: la herida «sopla» al respirar.','He was also hit in the chest: the wound “sucks” air with each breath.']);
  if(sec.includes('eye')) add.push(['Un fragmento le ha alcanzado un ojo.','A fragment has hit one eye.']);
  if(sec.includes('fx')) add.push(['Al caer se ha golpeado el antebrazo, que está deformado.','He hit his forearm as he fell; it is deformed.']);
  return [m[0]+(add.length?' '+add.map(a=>a[0]).join(' '):''),m[1]+(add.length?' '+add.map(a=>a[1]).join(' '):'')]; };
 cs.kit=[b.kit[0]+(sec.includes('chest')&&id!=='torax'?', sellos torácicos con válvula, agujas de descompresión 14 G de 8,25 cm':'')+(sec.includes('eye')?', protector ocular rígido':'')+(sec.includes('fx')?', férula':'')+'; antibióticos: cefadroxilo oral, ceftriaxona y moxifloxacino',
  b.kit[1]+(sec.includes('chest')&&id!=='torax'?', vented chest seals, 14 G 3.25" decompression needles':'')+(sec.includes('eye')?', rigid eye shield':'')+(sec.includes('fx')?', splint':'')+'; antibiotics: oral cefadroxil, ceftriaxone and moxifloxacin'];
 cs.steps=()=>{ let st=b.steps();
  if(o.single){ const q0=st[0].q; st[0]=stCover([ctx.place[0]+' '+q0[0],ctx.place[1]+' '+q0[1]]); } else st=st.filter(s=>s.m!=='CUF');
  if(o.noCuf) st=st.filter(s=>s.ph!=='cuf');
  if(kind!==b.abx) st=st.map(s=>s.m==='AB'?stAbx(cs.late?'std':kind):s); else if(cs.late) st=st.map(s=>s.m==='AB'?stAbx('std'):s);
  if(sec.includes('chest')){ st=st.filter(s=>!(s.m==='R'&&s.ph==='tfc')); let ai=st.findIndex(s=>s.m==='A'&&s.ph==='tfc'); if(ai<0) ai=st.findIndex(s=>s.ph==='tfc'&&s.m!=='M'); st.splice(ai,1,gTalk(),...gChest()); }
  if(sec.includes('eye')){ const k=st.findIndex(s=>s.m==='AB'); st.splice(k<0?st.length-2:k,0,gEye()); }
  if(sec.includes('fx')){ const k=st.findIndex(s=>s.m==='E'); st.splice(k,0,gSplint()); }
  return st; };
 return cs;
}
/* imprevistos: cada uno se dispara cuando su condición se cumple, a partir de un número de decisiones fijado por la semilla */
function gStep(g,ph,m,q,opts,extra){ const st=Object.assign({ph:ph,m:m,q:q,hint:extra&&extra.hint||['',''],opts:opts,glob:1},extra||{}); gOrd(st,g.r2); return st; }
function gEvents(g){ const E={};
 E.fuego={cond:()=>true,make:()=>gStep(g,'cuf','EV',['¡Imprevisto! Vuelven a disparar: el enemigo abre fuego otra vez sobre vuestra posición.','Surprise! The firing starts again: the enemy opens fire on your position once more.'],[
  O('Devolver el fuego, poner a cubierto a los heridos y seguir tratando cuando la posición sea segura','Return fire, get the casualties into cover and keep treating once the position is safe',OK,{t:40,end:()=>{ g.pts.forEach(P=>{ if(!P.dead&&!P.done) logc(P,'Fuego enemigo: a cubierto','Enemy fire: into cover'); }); }},['TCCC: con fuego enemigo vuelve la fase «bajo fuego»: lo primero es la superioridad de fuego y la cobertura. Un sanitario herido no salva a nadie.','TCCC: under enemy fire you are back in care under fire: fire superiority and cover come first. A wounded medic saves no one.']),
  O('Seguir tratando al descubierto, sin levantar la cabeza','Keep treating in the open, head down',NO,{t:45,h:{hr:6,sbp:-4}},['Al descubierto os exponéis los dos a una segunda herida. TCCC: con fuego, primero cobertura.','In the open you both risk being hit again. TCCC: under fire, cover first.']),
  O('Cargar con el herido y correr sin fuego de cobertura','Pick up the casualty and run without covering fire',NO,{t:60,h:{hr:8,sbp:-5}},['Sin fuego de cobertura es la forma más fácil de tener más bajas. TCCC: devolver el fuego y luego mover a cubierto.','Without covering fire it is the easiest way to take more casualties. TCCC: return fire, then move to cover.'])],
  {hint:['Cuando vuelve el fuego, vuelve la fase «bajo fuego»: superioridad de fuego y cobertura primero.','When the firing returns, so does care under fire: fire superiority and cover first.']})};
 E.lluvia={cond:()=>!g.ctx.wx.hot&&!g.ctx.env.hot&&g.ctx.wx.id!=='llu',make:()=>gStep(g,'tfc','EV',['¡Imprevisto! Empieza a llover con fuerza y sopla un viento frío. Los heridos se están mojando.','Surprise! Heavy rain starts and a cold wind picks up. The casualties are getting wet.'],[
  O('Proteger a todos: a resguardo de la lluvia, aislarles del suelo y cambiar la ropa mojada','Protect everyone: shelter from the rain, insulate from the ground and change wet clothes',OK,{t:60,end:()=>{ g.pts.forEach(P=>{ if(!P.dead&&!P.done){ P.wet=0; P.tDrop*=1.3; logc(P,'Lluvia: a resguardo, ropa seca','Rain: sheltered, dry clothes'); } }); }},['TCCC: minimizar la exposición al suelo frío, al viento y al aire; cambiar la ropa mojada por seca. La hipotermia empeora la coagulación.','TCCC: minimise exposure to cold ground, wind and air; replace wet clothing with dry. Hypothermia worsens clotting.']),
  O('Seguir: ya se secarán en el helicóptero','Carry on: they’ll dry off in the helicopter',NO,{t:15,end:()=>{ g.pts.forEach(P=>{ if(!P.dead&&!P.done&&!P.heat){ P.wet=1; P.tDrop*=1.3; } }); }},['Mojados y con viento pierden calor muy deprisa. TCCC pide medidas precoces contra la hipotermia en todos.','Wet and in the wind they lose heat very fast. TCCC wants early anti-hypothermia measures in everyone.'])])};
 E.kit={cond:()=>!g.pts.some(P=>!P.dead&&!P.done&&(P.cs.tpl==='frio'||P.cs.tpl==='quemado'))&&g.pts.some(P=>!P.dead&&!P.done&&P.steps.slice(P.step).some(s=>s.hy)),make:()=>gStep(g,'tfc','EV',['¡Imprevisto! Un impacto destroza la mochila con los kits de hipotermia (mantas activas y bolsas). ¿Cómo proteges del frío a los heridos?','Surprise! A hit destroys the backpack with the hypothermia kits (active heaters and bags). How do you protect the casualties from the cold?'],[
  O('Improvisar: aislarles del suelo con esterillas o mochilas, quitar la ropa mojada y meterles en sacos de dormir o mantas secas de la sección','Improvise: insulate them from the ground with mats or packs, remove wet clothing and put them in the section’s sleeping bags or dry blankets',OK,{t:90,end:()=>{ g.flags.noKit=1; g.pts.forEach(P=>{ if(!P.dead&&!P.done&&!P.heat){ P.ins=1; P.wet=0; logc(P,'Sin kit: aislado con saco y esterilla','No kit: insulated with bag and mat'); } }); }},['TCCC: aislar del suelo, cambiar la ropa mojada y usar un saco de dormir u otro aislamiento disponible. Sin manta activa no recupera calor, pero deja de perderlo (simplificado para el juego).','TCCC: insulate from the ground, change wet clothing and use a sleeping bag or other available insulation. Without an active heater he doesn’t regain heat, but stops losing it (simplified for the game).']),
  O('Nada: sin el kit no se puede hacer nada','Nothing: without the kit nothing can be done',NO,{t:15},['Sí se puede: TCCC acepta cualquier aislamiento disponible. Sin nada, siguen enfriándose.','Yes it can: TCCC accepts any available insulation. With nothing, they keep cooling.'])])};
 E.sangre={cond:()=>g.pts.some(P=>!P.dead&&!P.done&&P.steps.slice(P.step).some(s=>s.bl&&!s.pl)),make:()=>gStep(g,'tfc','EV',['¡Imprevisto! La nevera con la sangre total se ha perdido al cambiar de posición. Solo queda plasma liofilizado.','Surprise! The cooler with the whole blood was lost while changing position. Only freeze-dried plasma is left.'],[
  O('Entendido: si alguno está en shock, plasma liofilizado y reevaluar tras cada unidad','Understood: if anyone is in shock, freeze-dried plasma, reassessing after each unit',OK,{t:10,end:()=>{ g.flags.noBlood=1; g.pts.forEach(P=>{ P.steps=P.steps.map((s,i)=>i>=P.step&&s.bl&&!s.pl?gOrd(Object.assign(gPlasma(),{pl:1}),g.r2):s); if(P.steps[P.step]&&P.steps[P.step].pl) enterStep(g,P); }); }},['TCCC da un orden: sangre total; si no hay, componentes; y al final plasma o hematíes solos. Siempre reevaluando tras cada unidad.','TCCC gives an order: whole blood; if none, components; and finally plasma or red cells alone. Always reassessing after each unit.']),
  O('Entonces suero salino a chorro para todos','Then saline wide open for everyone',NO,{t:10},['El suero diluye y enfría la sangre. TCCC sigue con plasma antes que con suero en el shock hemorrágico.','Saline dilutes and cools the blood. TCCC moves to plasma before saline in haemorrhagic shock.'])])};
 E.radio={cond:()=>g.pts.some(P=>{ const s=P.steps[P.step]; return !P.dead&&!P.done&&s&&s.m==='E'&&s.ph==='tfc'; }),make:()=>gStep(g,'tfc','EV',['¡Imprevisto! Vas a pedir la evacuación y la radio no transmite: solo se oye ruido.','Surprise! You go to call the evacuation and the radio won’t transmit: only static.'],[
  O('Pasar al siguiente medio del plan de comunicaciones (radio alternativa o satélite) y repetir la petición','Switch to the next means in the communications plan (alternate radio or satellite) and repeat the request',OK,{t:60},['Las unidades llevan un plan de comunicaciones con medios de reserva (el plan PACE: principal, alternativo, contingencia, emergencia). Simplificado para el juego.','Units carry a communications plan with backup means (the PACE plan: primary, alternate, contingency, emergency). Simplified for the game.']),
  O('Esperar a que vuelva la radio','Wait for the radio to come back',NO,{t:180},['Cada minuto sin pedir la evacuación es un minuto más hasta el cirujano.','Every minute without calling the evacuation is another minute until the surgeon.']),
  O('Mandar a un soldado corriendo a la base','Send a soldier running back to base',NO,{t:120},['Lento y arriesgado, y te quedas con un hombre menos. Había medios de reserva.','Slow and risky, and you lose a man. There were backup means.'])])};
 E.helo={cond:()=>g.pts.some(P=>{ const s=P.steps[P.step]; return !P.dead&&!P.done&&s&&s.m==='E'&&s.ph==='evac'; })&&g.pts.every(P=>P.dead||P.done||bleedRate(P)<0.06),make:()=>{ const div=g.r2()<0.5; return gStep(g,'evac','EV',div?['¡Imprevisto! El helicóptero ha sido desviado a otra emergencia: el siguiente tardará 10 minutos más.','Surprise! The helicopter has been diverted to another emergency: the next one will be 10 minutes later.']:['¡Imprevisto! El helicóptero se retrasa 10 minutos por el mal tiempo en la ruta.','Surprise! The helicopter is 10 minutes late because of bad weather en route.'],[
  O('Aprovechar la espera: reevaluar a todos (torniquetes, constantes, temperatura) y preparar la zona de aterrizaje','Use the wait: reassess everyone (tourniquets, vitals, temperature) and prepare the landing zone',OK,{t:600,end:()=>{ g.pts.forEach(P=>{ if(!P.dead&&!P.done) logc(P,'Espera de 10 min: reevaluado','10-min wait: reassessed'); }); }},['TCCC pide reevaluar al herido a menudo y, sobre todo, los torniquetes y la temperatura mientras espera la evacuación.','TCCC asks you to reassess casualties often, especially tourniquets and temperature, while awaiting evacuation.']),
  O('Aflojar los torniquetes mientras esperáis, para salvar los miembros','Loosen the tourniquets while you wait, to save the limbs',NO,{t:600,end:()=>{ g.pts.forEach(P=>{ if(P.dead||P.done) return; P.tqs.forEach(q=>{ const w=wd(P,q.id); if(w&&w.ctl>=1&&w.rate>0.02*P.bv) P.lost+=w.rate*coagF(P)*1; }); }); }},['TCCC solo convierte un torniquete si no hay shock, se puede vigilar la herida, no es una amputación y lleva menos de 2 horas. Aflojar «para ganar tiempo» hace que vuelvan a sangrar.','TCCC only converts a tourniquet if there is no shock, the wound can be watched, it is not an amputation and it has been on under 2 hours. Loosening it “to buy time” makes them bleed again.'],'t26',2),
  O('Meterles en un vehículo sin escolta y salir por la carretera','Load them into a vehicle without escort and drive out',NO,{t:600,h:{hr:6,sbp:-6}},['Sin escolta, por una ruta insegura y sin sitio para tratar en marcha: más riesgo que esperar 10 minutos.','No escort, an unsafe route and no room to treat on the move: more risk than waiting 10 minutes.'])]); }};
 E.nuevo={cond:()=>g.pts.length<(g.mode==='r'?4:3),make:()=>{ const ids=g.pts.length>=3?(g.ctx.cold?['leve','frio']:['leve']):(g.ctx.cold?['leve','frio','pelvis']:['leve','pelvis','leve']); const ids2=ids.filter(x=>!g.pts.some(P=>P.cs.tpl===x)); const id=ids2.length?ids2[Math.floor(g.r2()*ids2.length)]:'pelvis';
  const cs=gCase(g.r2,id,{noCuf:1},g.ctx); const S=gPatient(g,cs,g.pts.length); g.pts.push(S); g.multi=true; enterStep(g,S); g.flags.newPt=S.id;
  return gStep(g,'tfc','EV',['¡Imprevisto! Traen a otro herido: '+S.id+', '+T(cs.title).toLowerCase()+'.','Surprise! Another casualty is brought in: '+S.id+', '+T(cs.title).toLowerCase()+'.'],[
   O('Triaje rápido (¿sangra mucho?, ¿respira?, ¿responde?) y seguir por orden de prioridad','Quick triage (heavy bleeding? breathing? responding?) and carry on in priority order',OK,{t:20,end:()=>logc(S,'Triaje rápido al llegar','Quick triage on arrival')},['Triaje: se clasifica a cada herido que llega y se atiende primero lo que antes mata. El nuevo no pasa delante solo por ser nuevo.','Triage: every new casualty is sorted on arrival and whatever kills first is treated first. The newcomer doesn’t jump the queue just for being new.'],'ews'),
   O('Dejar a medias al que tratas y empezar con el nuevo desde el principio','Drop the one you are treating and start the newcomer from scratch',NO,{t:30},['Sin triaje, cambias de herido sin saber quién está peor.','Without triage you switch casualties without knowing who is worse.'],'ews'),
   O('No mirarle hasta terminar con todos los demás','Don’t look at him until you finish all the others',NO,{t:5},['Si sangrara mucho, moriría esperando. Hay que clasificarle al llegar.','If he were bleeding heavily he would die waiting. He must be triaged on arrival.'],'ews')]); }};
 return E;
}
/* dilemas (decisiones de grupo): todas las respuestas cierran el dilema; las malas tienen consecuencias */
function gDilemmas(g){ const D=[]; const P=g.pts; const lim=P.filter(S=>GTPL[S.cs.tpl].lim);
 if(g.dl.tq&&lim.length>=2){ const a=lim[0], b=lim[1]; const RK={amputacion:3,muslo:2,brazo:1}; const big=RK[a.cs.tpl]>=RK[b.cs.tpl]?a:b;
  const apply=(X,Y)=>()=>{ ctl('w1')(X); addTQ(X,'w1','TQ1'); X.flags.cufTQ=1; logc(X,'Último torniquete','Last tourniquet'); const w=wd(Y,'w1'); w.ctl=Math.max(w.ctl,0.6); Y.flags.d1=1; logc(Y,'Presión directa (autoayuda), sin torniquete','Direct pressure (self-aid), no tourniquet'); g.cur=g.pts.indexOf(Y); };
  const ds=S=>S.id+' ('+T(S.cs.title).toLowerCase()+')';
  D.push(gStep(g,'cuf','DIL',['¡Dilema! Bajo fuego, solo te queda UN torniquete y '+a.id+' y '+b.id+' sangran a borbotones de una extremidad. ¿Qué haces?','Dilemma! Under fire you have only ONE tourniquet left and '+a.id+' and '+b.id+' are both spurting blood from a limb. What do you do?'],[
   O('Torniquete a '+a.id+'; a '+b.id+' le dices que apriete él mismo la herida con las dos manos hasta llegar a cubierto','Tourniquet on '+a.id+'; tell '+b.id+' to press on his own wound with both hands until you reach cover',big===a,{t:45,end:apply(a,b)},[big===a?'Bien: el torniquete va a la hemorragia mayor ('+ds(a)+'), que es la que antes mata, y TCCC pide al herido que pueda que controle él mismo su sangrado (autoayuda).':'El torniquete fue a la hemorragia menor: '+ds(b)+' sangraba más deprisa y solo tenía presión con las manos.',big===a?'Right: the tourniquet goes to the bigger bleed ('+ds(a)+'), which kills first, and TCCC asks a casualty who can to control his own bleeding (self-aid).':'The tourniquet went to the smaller bleed: '+ds(b)+' was bleeding faster with only hand pressure.'],'t26',big===a?0:2),
   O('Torniquete a '+b.id+'; a '+a.id+' le dices que apriete él mismo la herida con las dos manos hasta llegar a cubierto','Tourniquet on '+b.id+'; tell '+a.id+' to press on his own wound with both hands until you reach cover',big===b,{t:45,end:apply(b,a)},[big===b?'Bien: el torniquete va a la hemorragia mayor ('+ds(b)+'), que es la que antes mata, y TCCC pide al herido que pueda que controle él mismo su sangrado (autoayuda).':'El torniquete fue a la hemorragia menor: '+ds(a)+' sangraba más deprisa y solo tenía presión con las manos.',big===b?'Right: the tourniquet goes to the bigger bleed ('+ds(b)+'), which kills first, and TCCC asks a casualty who can to control his own bleeding (self-aid).':'The tourniquet went to the smaller bleed: '+ds(a)+' was bleeding faster with only hand pressure.'],'t26',big===b?0:2),
   O('Repartir: presión con la mano en los dos y guardar el torniquete','Split it: hand pressure on both and keep the tourniquet',NO,{t:60,end:()=>{ [a,b].forEach(S=>{ wd(S,'w1').ctl=Math.max(wd(S,'w1').ctl,0.5); S.flags.d1=1; }); g.cur=g.pts.indexOf(big); }},['Un torniquete guardado no salva a nadie. Bajo fuego, la hemorragia que amenaza la vida lleva torniquete ya.','A tourniquet in the bag saves no one. Under fire, life-threatening bleeding gets a tourniquet now.'],'t26',2)],
   {final:1,dl:['Un torniquete para dos: no hay opción perfecta. Va a quien sangra más deprisa (la amputación o el chorro arterial más grande), porque es quien antes muere, y el otro se ayuda a sí mismo apretando hasta que a cubierto llegue otro torniquete.','One tourniquet for two: there is no perfect option. It goes to the faster bleed (the amputation or the bigger arterial spurt), because he will die first, and the other helps himself by pressing until another tourniquet arrives in cover.']}));
  [a,b].forEach(S=>{ S.steps.forEach(s=>{ if(s.m==='M'&&!s.ev){ const w0=s.when; if(s.ph==='cuf') s.when=Q=>!Q.flags.cufTQ&&!Q.flags.d1&&(!w0||w0(Q)); else s.when=Q=>!Q.flags.d1&&(!w0||w0(Q)); } });
   const ci=S.steps.findIndex(s=>s.ph==='tfc'); S.steps.splice(ci,0,gOrd({ph:'tfc',m:'M',when:Q=>Q.flags.d1,q:['A cubierto. Un compañero te pasa el torniquete de su botiquín individual. '+S.id+' sigue apretando su herida y la sangre se escapa entre los dedos.','In cover. A teammate hands you the tourniquet from his own first-aid kit. '+S.id+' is still pressing on his wound and blood seeps between his fingers.'],hint:['Ahora sí: torniquete directo sobre la piel, 5-8 cm por encima de la herida, apretado hasta que pare.','Now: tourniquet directly on the skin, 5-8 cm above the wound, tightened until the bleeding stops.'],
    opts:[O('Torniquete sobre la piel 5-8 cm por encima, apretar hasta que pare y anotar la hora','Tourniquet on skin 5-8 cm above, tighten until it stops and note the time',OK,{t:60,end:Q=>{ctl('w1')(Q);addTQ(Q,'w1','TQ');logc(Q,'Torniquete sobre la piel','Tourniquet on skin');}},['TCCC: torniquete para la hemorragia de extremidad que amenaza la vida (y para toda amputación), sobre la piel a 5-8 cm por encima.','TCCC: tourniquet for life-threatening limb bleeding (and every amputation), on skin 5-8 cm above.']),
     O('Seguir solo con presión de la mano hasta el helicóptero','Keep hand pressure only until the helicopter',NO,{t:60},['La presión con la mano no basta para un sangrado arterial: sigue perdiendo sangre.','Hand pressure isn’t enough for arterial bleeding: he keeps losing blood.']),
     O('Vendaje compresivo encima y listo','A pressure bandage over it and that’s it',NO,{t:60,end:Q=>{ wd(Q,'w1').ctl=Math.max(wd(Q,'w1').ctl,0.6); }},['Un vendaje no para un chorro arterial ni una amputación.','A bandage won’t stop an arterial spurt or an amputation.'])]},g.r2)); });
 }
 if(g.dl.self){ const lv=P.find(S=>S.cs.tpl==='leve'), hv=P.find(S=>GTPL[S.cs.tpl].cat==='T1');
  if(lv&&hv) D.push(gStep(g,'cuf','DIL',['¡Dilema! Eres el único sanitario. '+lv.id+' tiene una herida leve, camina y habla; '+hv.id+' está grave. ¿Cómo te repartes?','Dilemma! You are the only medic. '+lv.id+' has a minor wound, walks and talks; '+hv.id+' is in a bad way. How do you split yourself?'],[
   O('Que '+lv.id+' se ponga su propio vendaje (autoayuda) y ayude vigilando; tú vas con '+hv.id,lv.id+' puts on his own bandage (self-aid) and helps keep watch; you go to '+hv.id,OK,{t:10,end:()=>{ ctl('w1')(lv); lv.flags.self=1; logc(lv,'Autoayuda: se venda él mismo','Self-aid: bandaged himself'); g.cur=g.pts.indexOf(hv); }},['El herido leve (T3) puede cuidarse solo e incluso ayudar; el sanitario va al herido grave. TCCC también pide la autoayuda a quien pueda.','The minimal casualty (T3) can look after himself and even help; the medic goes to the serious one. TCCC also asks for self-aid from anyone who can.'],'ews'),
   O('Atender primero a '+lv.id+', que es el que más se queja','Treat '+lv.id+' first, since he is complaining the most',NO,{t:120,end:()=>{ ctl('w1')(lv); lv.flags.self=1; g.cur=g.pts.indexOf(hv); }},['El que más grita no es el más grave. Dos minutos con el leve son dos minutos sin tratar al grave.','The one shouting loudest isn’t the most serious. Two minutes with the minor one are two minutes without treating the serious one.'],'ews',2)],
   {final:1,dl:['Un sanitario, varios heridos: el triaje manda tu tiempo al que puede morir en minutos, y el herido leve deja de ser un paciente para ser una ayuda.','One medic, several casualties: triage sends your time to whoever may die within minutes, and the minor casualty stops being a patient and becomes a helper.']}));
 }
 if(g.dl.exp){ const nm=g.ctx.name(); g.exp={id:String.fromCharCode(65+P.length),name:nm};
  D.push(gStep(g,'tfc','DIL',['¡Dilema! El soldado '+g.exp.id+' ('+nm+'), alcanzado de lleno por la explosión, no tiene pulso ni respira. No hay signos de vida. Los demás heridos te esperan.','Dilemma! Soldier '+g.exp.id+' ('+nm+'), caught full by the blast, has no pulse and is not breathing. No signs of life. The other casualties are waiting.'],[
   O('No empezar RCP: descompresión con aguja en los dos lados del pecho por si fuera un neumotórax a tensión; si sigue sin signos de vida, es expectante: cubrirle, apartarle de la vista y volver con los demás','No CPR: needle decompression on both sides of the chest in case of tension pneumothorax; if there are still no signs of life he is expectant: cover him, move him out of sight and go back to the others',OK,{t:60},['TCCC: en combate, la RCP de un herido por explosión o disparo sin pulso, sin respiración y sin signos de vida no tiene éxito y no debe intentarse; con trauma de torso, antes se descomprimen los dos lados. Al expectante no se le abandona: se le aparta de la vista y se le reevalúa.','TCCC: on the battlefield, CPR for a blast or gunshot casualty with no pulse, no breathing and no signs of life will not succeed and should not be attempted; with torso trauma, decompress both sides first. The expectant casualty is not abandoned: he is moved out of sight and reassessed.'],'t26'),
   O('Hacerle RCP hasta que llegue el helicóptero','Do CPR on him until the helicopter arrives',NO,{t:300},['Cinco minutos de RCP sin posibilidad de éxito mientras los demás sangran. TCCC: en el campo no se intenta en este caso.','Five minutes of CPR with no chance of success while the others bleed. TCCC: in the field it is not attempted in this case.'],'t26',2),
   O('Pasar de largo sin comprobar nada','Walk past without checking anything',NO,{t:5},['Hay que comprobarlo: con trauma de torso, TCCC pide descompresión en los dos lados antes de dejar de atenderle.','You must check: with torso trauma, TCCC calls for decompression on both sides before stopping care.'],'t26')],
   {final:1,dl:['El dilema más duro del triaje: en combate, un herido sin pulso ni respiración tras una explosión no se recupera con RCP, y cada minuto que se le dedica se le quita a los que sí se pueden salvar. Se le comprueba, se le acompaña con respeto y se sigue.','The hardest triage dilemma: in combat, a casualty with no pulse or breathing after a blast does not come back with CPR, and every minute spent on him is taken from those who can be saved. He is checked, treated with respect, and the medic moves on.']}));
 }
 return D;
}
function gSeat(g){ return {cond:()=>{ const live=g.pts.filter(P=>!P.dead&&!P.done); if(live.length<2) return false; const at=live.find(P=>{ const s=P.steps[P.step]; return s&&s.m==='E'&&s.ph==='evac'; }); if(!at) return false; const cats=live.map(P=>P.cs.cat); return cats.some(c=>c!=='T1')&&cats.includes('T1'); },
 make:()=>{ const live=g.pts.filter(P=>!P.dead&&!P.done); const rk={T1:0,T2:1,T3:2};
  const best=live.reduce((a,P)=>rk[P.cs.cat]<rk[a.cs.cat]?P:a,live[0]);
  return gStep(g,'evac','DIL',['¡Dilema! El helicóptero solo tiene sitio para UNA camilla ahora; el segundo vuelo llegará dentro de 30 minutos. ¿A quién subes?','Dilemma! The helicopter only has room for ONE litter now; the second lift arrives in 30 minutes. Who goes up?'],
   live.map(P=>O(P.id+' · '+T(P.cs.title),P.id+' · '+T(P.cs.title),P===best||P.cs.cat===best.cs.cat,{t:30,end:()=>{ const sent=P; if(sent.cs.cat!=='T1'){ live.filter(Q=>Q!==sent&&Q.cs.cat==='T1').forEach(Q=>{ Q.off.hr+=10; Q.off.sbp-=10; Q.errors++; Q.crit++; sim(Q,1200); logc(Q,'Espera 30 min al segundo vuelo','Waits 30 min for the second lift'); }); } g.flags.seat=sent.id; }},
    [P.cs.cat==='T1'?'Bien: sube el herido inmediato (T1), el que tiene precedencia urgente. Los diferidos o leves pueden esperar al segundo vuelo sin peligro inmediato.':'Este herido es '+T(GCAT[P.cs.cat]).toLowerCase()+': puede esperar. El herido urgente se queda 30 minutos más sin cirujano y empeora.',P.cs.cat==='T1'?'Right: the immediate casualty (T1), with urgent precedence, goes up. Delayed or minimal casualties can wait for the second lift without immediate danger.':'This casualty is '+T(GCAT[P.cs.cat]).toLowerCase()+': he can wait. The urgent casualty stays 30 more minutes without a surgeon and deteriorates.'],'ews',P.cs.cat==='T1'?0:2)),
   {final:1,dl:['Un asiento, varios heridos: sube quien tiene la precedencia más alta en la petición de 9 líneas (urgente antes que prioritario o rutina). No es justo ni injusto: es lo que salva más vidas.','One seat, several casualties: the one with the highest 9-line precedence goes (urgent before priority or routine). It isn’t fair or unfair: it is what saves the most lives.']}); }}; }

function gPatient(g,cs,k){ const S=newState(cs,(g.seed*2654435761+k*977+g.att*7919)>>>0); S.id=String.fromCharCode(65+k);
 const lv=g.lv; S.thr=lv.thr; S.tenLim=lv.ten; S.spLim=lv.sp; S.dec=lv.dec;
 const raw=cs.steps(); S.steps=[]; raw.forEach(st=>{ S.steps.push(st); if(st.m==='AB') S.steps.push(stAnaph()); });
 S.wounds.forEach(w=>{ if(w.x==null){ const p=wpos(w.at,w.fixed||S.side); w.x=p[0]; w.y=p[1]; if(w.amp) w.y=234; if(w.id==='h1') w.y+=10; } });
 const r=rng(S.seed^0x9e3779b9); S.steps.forEach(st=>gOrd(st,r));
 if(cs.tpl==='torax'&&g.multi){ S.tension=0.25; S.tensGrow=1/500; }
 return S; }
function gBuild(spec,att){
 const lv=LEVELS[spec.mode]||LEVELS.r; const seed=(spec.gen>>>0)||1;
 const r=rng((seed^(att*0x2545F491))>>>0);
 const pick=a=>a[Math.floor(r()*a.length)];
 const g={mode:spec.mode,lv:lv,seed:seed,att:att,gen:1,multi:false,scen:null,cur:0,ff:null,fb:null,end:0,t:0,pre:[],hl:null,ban:null,acts:0,flags:{},evq:[],evlog:[]};
 g.r2=rng((seed*31+att*101+7)>>>0);
 const env=pick(GTERR); let wx=pick(GWX); if(env.hot&&wx.cold) wx=GWX[3]; if(env.cold&&wx.hot) wx=GWX[2];
 const hour=pick(GHOUR); const used={}; const nm=()=>{ let n; let k=0; do{ n=pick(GNAMES); k++; }while(used[n]&&k<40); used[n]=1; return n; };
 const ctx={env:env,wx:wx,hour:hour,cold:!!(env.cold||wx.cold||wx.wet),name:nm}; g.ctx=ctx;
 /* cuántos heridos */
 const easy=att>=9; const n=easy?1:spec.mode==='r'?pick([1,2,2,2,3,3]):pick([1,1,2]);
 /* mecanismo principal y plantillas compatibles */
 const pools={gsw:['muslo','brazo','torax','leve'],ied:['amputacion','cabeza','pelvis','leve','muslo'],frag:['ingle','brazo','leve','torax'],fire:['quemado','leve','pelvis'],roll:['pelvis','cabeza','leve','brazo'],cold:['frio','leve','muslo']};
 let mx=pick(['gsw','gsw','ied','ied','frag','fire','roll']); if(ctx.cold&&r()<0.25) mx='cold';
 const ids=[]; for(let i=0;i<n;i++){ const pool=pools[mx].filter(x=>!ids.includes(x)||x==='muslo'||x==='brazo'); ids.push(i===0?pools[mx][Math.floor(r()*(pools[mx].length-1))]:i===2?(ids.includes('leve')?(ctx.cold&&!ids.includes('frio')?'frio':(pick(pool.filter(x=>x!=='pelvis'&&x!=='amputacion'&&x!=='quemado'&&x!=='cabeza'))||'brazo')):(ctx.cold&&r()<0.4&&!ids.includes('frio')?'frio':'leve')):pick(pool)); }
 /* dilemas posibles */
 g.dl={};
 if(n>=2&&r()<0.38){ const lims=mx==='ied'?['muslo','brazo','amputacion']:['muslo','brazo']; if(!lims.includes(ids[0])) ids[0]=pick(lims); if(!lims.includes(ids[1])||ids[1]===ids[0]) ids[1]=pick(lims.filter(x=>x!==ids[0])); for(let i=2;i<ids.length;i++) if(lims.includes(ids[i])) ids[i]='leve'; g.dl.tq=1; }
 if(n>=2&&ids.includes('leve')&&ids.some(x=>GTPL[x].cat==='T1')) g.dl.self=1;
 if(n>=2&&mx==='ied'&&spec.mode==='r'&&r()<0.5) g.dl.exp=1;
 /* módulos secundarios */
 const secs=ids.map(id=>{ const s=[]; const q=r();
  if(['muslo','brazo','amputacion','ingle'].includes(id)&&q<0.22&&!(g.dl.tq&&(id==='muslo'||id==='brazo'||id==='amputacion'))) s.push('chest');
  else if(['leve','muslo','brazo','ingle','amputacion','torax','frio'].includes(id)&&q<0.42&&(mx==='frag'||mx==='ied')) s.push('eye');
  if(['leve','cabeza','torax','ingle','amputacion','pelvis'].includes(id)&&r()<0.25&&(mx==='roll'||mx==='ied'||mx==='frag')) s.push('fx');
  return s; });
 /* imprevistos */
 const evn=spec.mode==='r'?pick([2,2,3]):pick([1,2]);
 const cand=['fuego','lluvia','kit','sangre','radio','helo','nuevo','oculta','alergia'];
 const evs=shuf(cand,r).slice(0,evn+1);
 const hasEv=k=>evs.includes(k);
 let hid=-1; if(hasEv('oculta')){ hid=ids.findIndex(x=>['muslo','brazo','torax','pelvis','ingle'].includes(x)); }
 let late=-1; if(hasEv('alergia')) late=ids.findIndex(x=>x!=='quemado'&&x!=='pelvis');
 const single=n===1;
 const cap=x=>x.charAt(0).toUpperCase()+x.slice(1);
 const intro=[cap(hour[0])+', '+env.t[0]+', '+wx.t[0]+'. '+T0(GINTRO[mx],0),cap(hour[1])+', '+env.t[1]+', '+wx.t[1]+'. '+T0(GINTRO[mx],1)];
 ctx.intro=intro; ctx.place=[cap(hour[0])+', '+env.t[0]+', '+wx.t[0]+'.',cap(hour[1])+', '+env.t[1]+', '+wx.t[1]+'.'];
 const css=ids.map((id,k)=>gCase(r,id,{single:single,sec:secs[k],hidden:k===hid,late:k===late},ctx));
 g.multi=!single;
 g.pts=css.map((cs,k)=>gPatient(g,cs,k));
 if(late>=0&&!g.pts[late].cs.late) late=-1;
 if(g.multi){
  g.pre.push(gStep(g,'cuf','CUF',['Os disparan y hay varios heridos. '+intro[0]+' ¿Qué haces primero?','You are under fire with several casualties. '+intro[1]+' What do you do first?'],[
   O('Devolver el fuego y ponerme a cubierto con mi equipo','Return fire and take cover with my team',OK,{t:20},['TCCC, bajo fuego, punto 1: devolver el fuego y ponerse a cubierto.','TCCC, care under fire, step 1: return fire and take cover.']),
   O('Correr al descubierto hacia el herido más cercano','Run across open ground to the nearest casualty',NO,{t:75},['El fuego os inmoviliza más de un minuto; mientras, todos siguen sangrando.','Fire pins you down for over a minute; meanwhile everyone keeps bleeding.'])]));
  const cats=g.pts.map(S=>S.cs.cat).concat(g.dl.exp?['T4']:[]); let triSt=null;
  if(new Set(cats).size>=2){ const lab=cs=>cs.map((c,i)=>String.fromCharCode(65+i)+': '+T0(GCAT[c],0).split(' (')[0]).join(' · '), labE=cs=>cs.map((c,i)=>String.fromCharCode(65+i)+': '+T0(GCAT[c],1).split(' (')[0]).join(' · ');
   const alts=[]; const order=['T1','T2','T3','T4']; for(let i=0;i<cats.length&&alts.length<2;i++){ const c2=cats.slice(); const j=order.indexOf(cats[i]); c2[i]=order[(j+1+(alts.length))%3]; if(c2.join()!==cats.join()&&!alts.some(a=>a.join()===c2.join())) alts.push(c2); }
   triSt=(gStep(g,'tfc','TRI',['Triaje a cubierto: clasifica a los heridos.'+(g.dl.exp?' '+String.fromCharCode(65+g.pts.length)+' no tiene pulso ni respira.':''),'Triage in cover: sort the casualties.'+(g.dl.exp?' '+String.fromCharCode(65+g.pts.length)+' has no pulse and is not breathing.':'')],
    [O(lab(cats),labE(cats),OK,{t:15},[cats.map((c,i)=>String.fromCharCode(65+i)+' es '+T0(GCAT[c],0).toLowerCase()+': '+T0(GCATW[c],0)).join('. ')+'.',cats.map((c,i)=>String.fromCharCode(65+i)+' is '+T0(GCAT[c],1).toLowerCase()+': '+T0(GCATW[c],1)).join('. ')+'.'],'ews')].concat(alts.map(a=>O(lab(a),labE(a),NO,{t:15},['Clasificación equivocada. '+cats.map((c,i)=>String.fromCharCode(65+i)+' es '+T0(GCAT[c],0).toLowerCase()).join(', ')+'.','Wrong sort. '+cats.map((c,i)=>String.fromCharCode(65+i)+' is '+T0(GCAT[c],1).toLowerCase()).join(', ')+'.'],'ews'))),
    {hint:['Inmediato (T1): muere en minutos sin ayuda. Diferido (T2): puede esperar un poco. Leve (T3): se cuida solo. Expectante (T4): sin signos de vida.','Immediate (T1): dies within minutes without help. Delayed (T2): can wait a little. Minimal (T3): looks after himself. Expectant (T4): no signs of life.']})); }
  const D=gDilemmas(g);
  const expD=D.filter(d=>d.q[0].indexOf('no tiene pulso')>0); const othD=D.filter(d=>expD.indexOf(d)<0);
  if(!g.dl.tq){ const mass=g.pts.map((S,k)=>[k,S.wounds.reduce((a,w)=>a+(w.hidden?0:w.rate),0)]).filter(x=>x[1]>=0.08*g.pts[x[0]].bv*0.9);
   if(mass.length){ const mx_=Math.max(...mass.map(x=>x[1])); const okk=mass.filter(x=>x[1]>=mx_*0.999).map(x=>x[0]);
    g.pre.push(gStep(g,'cuf','TRI',['Bajo fuego: ¿a quién vas primero?','Under fire: who do you go to first?'],g.pts.map((S,k)=>O(S.id+' · '+T(S.cs.title),S.id+' · '+T(S.cs.title),okk.includes(k),{t:5,end:()=>{g.cur=k;}},['Primero la hemorragia masiva que más deprisa sangra: es lo que antes mata y bajo fuego se para en segundos. Luego, a cubierto, los demás en orden MARCH.','First the fastest massive bleed: it kills soonest and under fire it is stopped in seconds. Then, in cover, the others in MARCH order.'])))); }
   else g.cur=gPrio(g); }
  othD.forEach(d=>g.pre.push(d));
  const inCover=()=>g.pts.every(P=>P.dead||P.done||!P.steps[P.step]||P.steps[P.step].ph!=='cuf');
  if(triSt) g.evq.push({k:'tri',at:0,ev:{cond:inCover,make:()=>triSt}});
  expD.forEach(d=>g.evq.push({k:'exp',at:0,ev:{cond:inCover,make:()=>d}}));
 }
 /* imprevistos programados */
 const E=gEvents(g);
 let at=single?3:4; evs.forEach(k=>{ if(k==='oculta'||k==='alergia') return; if(E[k]) { g.evq.push({k:k,at:at+Math.floor(r()*3),ev:E[k]}); at+=2+Math.floor(r()*4); } });
 if(hid>=0) g.evq.push({k:'oculta',pt:hid,at:2});
 if(late>=0) g.evq.push({k:'alergia',pt:late,at:0});
 if(g.multi) g.evq.push({k:'asiento',at:0,ev:gSeat(g)});
 g.mx=mx; g.titleF=()=>[T0(GMX[mx],0)+' · '+env.s[0]+', '+hour[2]+', '+wx.s[0]+' · '+g.pts.length+(g.pts.length>1?' heridos':' herido'),T0(GMX[mx],1)+' · '+env.s[1]+', '+hour[3]+', '+wx.s[1]+' · '+g.pts.length+(g.pts.length>1?' casualties':' casualty')];
 g.desc=[intro[0],intro[1]];
 g.pts.forEach(S=>enterStep(g,S));
 return g;
}
const T0=(a,i)=>a[i];
const GINTRO={gsw:['Os emboscan con fuego de fusil.','You are ambushed with rifle fire.'],ied:['Un artefacto explosivo estalla al paso de la patrulla y luego llegan los disparos.','An explosive device goes off as the patrol passes and then the shooting starts.'],frag:['Caen granadas de mortero cerca de la posición.','Mortar rounds land near the position.'],fire:['Un vehículo arde tras un impacto y hay disparos.','A vehicle is burning after a hit and there is gunfire.'],roll:['Un vehículo vuelca al esquivar una explosión y os disparan.','A vehicle rolls over dodging a blast and you come under fire.'],cold:['Al cruzar un río, una explosión y disparos.','Crossing a river: an explosion and gunfire.']};
/* se llama tras cada decisión: dispara los imprevistos cuya hora y condición se cumplen */
function gTick(g){ if(!g.gen||g.end) return; g.acts++; if(g.pts.every(P=>P.dead||P.done)) return;
 for(const e of g.evq){ if(e.done||g.acts<e.at) continue;
  if(e.k==='oculta'){ const S=g.pts[e.pt]; if(!S||S.dead||S.done) { e.done=1; continue; } const st=S.steps[S.step]; if(!st||st.ph!=='tfc'||!['H','P','AB','W','S'].includes(st.m)||g.pre.length) continue;
   const w=wd(S,'h1'); if(w) w.hidden=0; const ns=gOrd(gHidden(),g.r2); S.steps.splice(S.step,0,ns); enterStep(g,S); e.done=1; g.evlog.push(['Herida oculta en '+S.id,'Hidden wound on '+S.id]); g.cur=g.pts.indexOf(S); logc(S,'Herida oculta descubierta','Hidden wound found'); continue; }
  if(e.k==='alergia'){ const S=g.pts[e.pt]; if(!S||S.dead||S.done){ e.done=1; continue; } const st=S.steps[S.step]; if(!st||st.m!=='AB'||st._alg||g.pre.length) continue;
   e.done=1; const real=S.cs.allergyReal; const kind=S.cs.abx;
   g.pre.push(gStep(g,'tfc','EV',['¡Imprevisto! Un compañero que conoce a '+S.id+' ('+S.name+') te avisa: «¡Es alérgico a '+T0(real,0).split(' (')[0]+'! Le dio '+T0(real,0).split(' (')[1].replace(')','')+'».','Surprise! A teammate who knows '+S.id+' ('+S.name+') warns you: “He’s allergic to '+T0(real,1).split(' (')[0]+'! He had '+T0(real,1).split(' (')[1].replace(')','')+'.”'],[
    O('Anotarlo en la tarjeta TCCC y elegir el antibiótico teniendo en cuenta la alergia','Write it on the TCCC card and choose the antibiotic with the allergy in mind',OK,{t:15,end:()=>{ S.cs.allergy=real; const ns=gOrd(stAbx(kind),g.r2); ns._alg=1; S.steps.splice(S.step,1,ns); S.steps[S.step]._in=1; g.cur=g.pts.indexOf(S); logc(S,'Alergia descubierta: '+T0(real,0),'Allergy found: '+T0(real,1)); }},['Las alergias se preguntan y se anotan siempre antes de un fármaco: un antibiótico equivocado puede causar una anafilaxia.','Allergies are always asked about and recorded before any drug: the wrong antibiotic can cause anaphylaxis.']),
    O('No hacer caso: ya tenía pensado el antibiótico','Ignore it: you had already picked the antibiotic',NO,{t:5},['Si das el antibiótico al que es alérgico, puede sufrir una anafilaxia. Hay que reconsiderarlo.','If you give the antibiotic he is allergic to, he may go into anaphylaxis. You must reconsider.'])]));
   g.evlog.push(['Alergia descubierta tarde en '+S.id,'Late-discovered allergy on '+S.id]); continue; }
  if(g.pre.length) continue;
  if(!e.ev.cond()) continue;
  const st=e.ev.make(); if(!st) { e.done=1; continue; } e.done=1; g.pre.push(st); g.evlog.push(st.q); }
}
/* casos infinitos: cada decisión cuenta exactamente el tiempo de pensar con el que genGame valida la partida (GTH: 10 s de juego en Realista, 6 s en Fácil y Aprende).
   Si el jugador piensa más, el herido espera; si contesta antes, el resto pasa al elegir. Así, jugando lo correcto a cualquier ritmo, la partida es la que se validó y el herido se salva. */
const GTH=m=>m==='r'?10:6;
function genGame(spec){ let g=null;
 for(let att=0;att<12;att++){ const t=gBuild(spec,att); const th=GTH(spec.mode);
  const strat=(g_,S,st)=>{ for(let i=0;i<st.opts.length;i++){ const o=st.opts[i]; if(typeof o.ok==='function'?o.ok(S):o.ok) return i; } return 0; }; strat.next=gPrio;
  playHeadless(t,strat,th); const ok=t.pts.every(S=>outcome(S)==='ok')&&t.acts>0;
  if(ok||att===11){ g=gBuild(spec,att); g.tries=att; break; } }
 return g; }


