 if(P_.m&&!LEVELS[P_.m]) P_.m='r';
 if(G&&SPEC&&!G.end&&((P_.c&&P_.c===SPEC.cs)||(P_.i&&P_.i===SPEC.scen)||(P_.g&&SPEC.gen!=null&&String(SPEC.gen)===P_.g))){ renderGame(); return; }
 if(P_.g&&/^\d+$/.test(P_.g)){ start({mode:P_.m||'r',gen:parseInt(P_.g,10)>>>0}); return; }
 if((P_.c&&caseById(P_.c))||(P_.i&&SCEN.find(s=>s.id===P_.i))){ start({mode:P_.m||'r',cs:P_.c||null,scen:P_.i||null,seed:/^\d+$/.test(P_.s||'')?(parseInt(P_.s,10)>>>0):((Math.random()*1e9)>>>0)}); return; }
 G=null; intro();
