 const tri=G.gen&&G.pts.length>1?'<section class="mddb"><div class="hd"><b>'+L('Triaje correcto','Correct triage')+'</b></div><ul class="mdtri">'+G.pts.map(S=>'<li><b>'+S.id+' · '+esc(T(GCAT[S.cs.cat]))+'</b> '+esc(T(S.cs.title))+': '+esc(T(GCATW[S.cs.cat]))+'.</li>').join('')+(G.exp?'<li><b>'+G.exp.id+' · '+esc(T(GCAT.T4))+'</b> '+esc(L('Sin signos de vida tras la explosión. No se le abandona: se le aparta de la vista y se le reevalúa.','No signs of life after the blast. He is not abandoned: he is moved out of view and reassessed.'))+'</li>':'')+'</ul><p class="mdmu">'+L('Categorías de Emergency War Surgery (cap. 3) y TCCC.','Categories from Emergency War Surgery (ch. 3) and TCCC.')+'</p></section>':'';
